//! `b10x-domain-graph/1` documents from the compiled ESS model (`ess specify compile --format json`).
//!
//! Docs System refuses a relation whose target is not an entity of the same document. A domain
//! that references an entity of another domain therefore carries that entity as well, with its
//! identity and no fields, so the edge is drawn and the entity's own domain page holds the rest.
use serde_json::{Map, Value, json};

/// Recorded in each document's `domain.source`, since JSON carries no comment.
pub const SOURCE: &str =
    "generated by patchback-docs from spec/ (ess specify compile); do not edit";

/// The summary of the whole-system graph, which no single domain names.
pub const SYSTEM_SUMMARY: &str =
    "Every entity of the Patchback specification and the relations between them.";

fn text<'a>(value: &'a Value, key: &str) -> Result<&'a str, String> {
    value[key]
        .as_str()
        .ok_or_else(|| format!("compiled model: `{key}` is not a string in {value}"))
}

fn strings(value: &Value) -> Vec<Value> {
    value
        .as_array()
        .map(|items| {
            items
                .iter()
                .filter(|item| item.is_string())
                .cloned()
                .collect()
        })
        .unwrap_or_default()
}

/// The last segment of a fully qualified name.
fn short(name: &str) -> &str {
    name.rsplit('.').next().unwrap_or(name)
}

/// A type reference as the graph shows it: `PatchId`, `integer`, `Optional<Decimal>`,
/// `Map<string, ParameterValue>`.
pub fn type_name(reference: &Value) -> Result<String, String> {
    let kind = text(reference, "kind")?;
    match kind {
        "primitive" => Ok(text(reference, "name")?.to_owned()),
        "declared" => Ok(short(text(reference, "name")?).to_owned()),
        "map" => Ok(format!(
            "Map<{}, {}>",
            text(reference, "key")?,
            type_name(&reference["value"])?
        )),
        _ => {
            let Some(of) = reference.get("of") else {
                return Err(format!(
                    "compiled model: unsupported type reference {reference}"
                ));
            };
            let mut wrapper = kind.to_owned();
            wrapper[..1].make_ascii_uppercase();
            Ok(format!("{wrapper}<{}>", type_name(of)?))
        }
    }
}

fn field(value: &Value) -> Result<Value, String> {
    Ok(json!({"name": text(value, "name")?, "type": type_name(&value["type_ref"])?}))
}

fn lifecycle(value: &Value) -> Result<Value, String> {
    let mut out = Map::new();
    out.insert("initial".into(), json!(text(value, "initial")?));
    out.insert("states".into(), Value::Array(strings(&value["states"])));
    let terminal = strings(&value["terminal"]);
    if !terminal.is_empty() {
        out.insert("terminal".into(), Value::Array(terminal));
    }
    if let Some(transitions) = value["transitions"].as_array() {
        let transitions = transitions
            .iter()
            .map(|transition| {
                Ok(json!({
                    "name": text(transition, "name")?,
                    "from": strings(&transition["from"]),
                    "to": text(transition, "to")?,
                }))
            })
            .collect::<Result<Vec<_>, String>>()?;
        if !transitions.is_empty() {
            out.insert("transitions".into(), Value::Array(transitions));
        }
    }
    Ok(Value::Object(out))
}

/// One entity in full: identity, fields and lifecycle.
fn entity_node(model: &Value, name: &str) -> Result<Value, String> {
    let entity = &model["entities"][name];
    if !entity.is_object() {
        return Err(format!("compiled model: no entity {name}"));
    }
    let mut out = Map::new();
    out.insert("id".into(), json!(name));
    out.insert("name".into(), json!(short(name)));
    out.insert("identity".into(), field(&entity["identity"])?);
    let fields = entity["fields"]
        .as_array()
        .map(|fields| fields.iter().map(field).collect::<Result<Vec<_>, String>>())
        .transpose()?
        .unwrap_or_default();
    out.insert("fields".into(), Value::Array(fields));
    if entity["lifecycle"].is_object() {
        out.insert("lifecycle".into(), lifecycle(&entity["lifecycle"])?);
    }
    Ok(Value::Object(out))
}

/// An entity of another domain, as a relation target: its identity only.
fn foreign_node(model: &Value, name: &str) -> Result<Value, String> {
    let entity = &model["entities"][name];
    if !entity.is_object() {
        return Err(format!("compiled model: no entity {name}"));
    }
    Ok(json!({
        "id": name,
        "name": short(name),
        "identity": field(&entity["identity"])?,
        "fields": [],
    }))
}

/// The relations declared on `name`, as graph edges.
fn relations_of(model: &Value, name: &str) -> Result<Vec<Value>, String> {
    let mut edges = Vec::new();
    for relation in model["entities"][name]["relations"]
        .as_array()
        .into_iter()
        .flatten()
    {
        let mut edge = Map::new();
        edge.insert("from".into(), json!(name));
        edge.insert("to".into(), json!(text(relation, "target")?));
        edge.insert("name".into(), json!(text(relation, "name")?));
        edge.insert("kind".into(), json!(text(relation, "kind")?));
        edge.insert("cardinality".into(), json!(text(relation, "cardinality")?));
        if let Some(via) = relation["via"].as_str() {
            edge.insert("via".into(), json!(via));
        }
        edges.push(Value::Object(edge));
    }
    Ok(edges)
}

/// A document over `names`, the entities drawn in full; relation targets outside them are added
/// as foreign nodes.
fn graph(model: &Value, header: Map<String, Value>, mut names: Vec<&str>) -> Result<Value, String> {
    names.sort_unstable();
    let mut entities = Vec::new();
    let mut relations = Vec::new();
    for name in &names {
        entities.push(entity_node(model, name)?);
        relations.extend(relations_of(model, name)?);
    }
    let mut foreign: Vec<&str> = relations
        .iter()
        .filter_map(|edge| edge["to"].as_str())
        .filter(|target| !names.contains(target))
        .collect();
    foreign.sort_unstable();
    foreign.dedup();
    for name in foreign {
        entities.push(foreign_node(model, name)?);
    }
    Ok(json!({
        "format": "b10x-domain-graph/1",
        "domain": Value::Object(header),
        "entities": entities,
        "relations": relations,
    }))
}

/// One domain of the compiled model as a `b10x-domain-graph/1` document.
pub fn domain_graph(model: &Value, domain: &str) -> Result<Value, String> {
    let declared = &model["domains"][domain];
    let naming = &declared["naming"];
    let mut header = Map::new();
    header.insert("id".into(), json!(domain));
    for key in ["display", "summary"] {
        if let Some(value) = naming[key].as_str() {
            header.insert(key.into(), json!(value));
        }
    }
    header.insert("system".into(), json!(text(model, "system")?));
    header.insert("source".into(), json!(SOURCE));
    let names: Vec<&str> = declared["entities"]
        .as_array()
        .ok_or_else(|| format!("compiled model: domain {domain} lists no entities"))?
        .iter()
        .filter_map(Value::as_str)
        .collect();
    graph(model, header, names)
}

/// Every domain of the compiled model, keyed by domain id.
pub fn domain_graphs(model: &Value) -> Result<Vec<(String, Value)>, String> {
    let domains = model["domains"]
        .as_object()
        .ok_or("compiled model has no domains")?;
    domains
        .keys()
        .map(|domain| Ok((domain.clone(), domain_graph(model, domain)?)))
        .collect()
}

/// Every entity of the compiled model in one document, for the landing page.
pub fn system_graph(model: &Value) -> Result<Value, String> {
    let system = text(model, "system")?;
    let mut header = Map::new();
    header.insert("id".into(), json!(system));
    header.insert("display".into(), json!("Patchback"));
    header.insert("summary".into(), json!(SYSTEM_SUMMARY));
    header.insert("system".into(), json!(system));
    header.insert("source".into(), json!(SOURCE));
    let names: Vec<&str> = model["entities"]
        .as_object()
        .ok_or("compiled model has no entities")?
        .keys()
        .map(String::as_str)
        .collect();
    graph(model, header, names)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn model() -> Value {
        let identity = |name: &str| json!({"name": name, "type_ref": {"kind": "declared", "name": format!("x.{name}")}});
        json!({
            "system": "patchback",
            "domains": {
                "x.patch": {"entities": ["x.patch.Patch"],
                            "naming": {"display": "Patches", "summary": "An editable DSP program."}},
                "x.fit": {"entities": ["x.fit.FitRun"],
                          "naming": {"display": "Fit runs", "summary": "One closed-loop fit."}}
            },
            "entities": {
                "x.patch.Patch": {
                    "identity": identity("PatchId"),
                    "fields": [{"name": "topology_id", "type_ref": {"kind": "optional", "of": {"kind": "primitive", "name": "String"}}}],
                    "lifecycle": {"initial": "Draft", "states": ["Draft", "Validated"], "terminal": [],
                                  "transitions": [{"name": "Validate", "from": ["Draft"], "to": "Validated"}]}
                },
                "x.fit.FitRun": {
                    "identity": identity("FitRunId"),
                    "fields": [{"name": "loss", "type_ref": {"kind": "declared", "name": "x.fit.Loss"}}],
                    "relations": [{"name": "best", "target": "x.patch.Patch",
                                   "kind": "references", "cardinality": "one", "via": "best_patch"}]
                }
            }
        })
    }

    #[test]
    fn a_relation_into_another_domain_carries_its_target_as_an_identity_only_entity() {
        let graph = domain_graph(&model(), "x.fit").unwrap();
        let entities = graph["entities"].as_array().unwrap();
        assert_eq!(entities.len(), 2);
        assert_eq!(entities[0]["id"], "x.fit.FitRun");
        assert_eq!(entities[0]["fields"][0]["type"], "Loss");
        assert_eq!(entities[1]["id"], "x.patch.Patch");
        assert_eq!(entities[1]["identity"]["type"], "PatchId");
        assert_eq!(entities[1]["fields"], json!([]));
        assert!(entities[1].get("lifecycle").is_none());
        assert_eq!(graph["relations"][0]["to"], "x.patch.Patch");
        assert_eq!(graph["relations"][0]["via"], "best_patch");
        assert_eq!(graph["domain"]["display"], "Fit runs");
        assert_eq!(graph["domain"]["source"], SOURCE);
    }

    #[test]
    fn a_domain_without_outgoing_relations_draws_only_its_own_entities() {
        let graph = domain_graph(&model(), "x.patch").unwrap();
        assert_eq!(graph["entities"].as_array().unwrap().len(), 1);
        assert_eq!(
            graph["entities"][0]["fields"][0]["type"],
            "Optional<String>"
        );
        assert_eq!(
            graph["entities"][0]["lifecycle"]["transitions"][0]["to"],
            "Validated"
        );
        assert!(graph["entities"][0]["lifecycle"].get("terminal").is_none());
        assert_eq!(graph["relations"], json!([]));
    }

    #[test]
    fn the_system_graph_holds_every_entity_in_full_and_every_relation() {
        let graph = system_graph(&model()).unwrap();
        let ids: Vec<&str> = graph["entities"]
            .as_array()
            .unwrap()
            .iter()
            .map(|entity| entity["id"].as_str().unwrap())
            .collect();
        assert_eq!(ids, ["x.fit.FitRun", "x.patch.Patch"]);
        assert!(graph["entities"][1]["lifecycle"].is_object());
        assert_eq!(graph["relations"].as_array().unwrap().len(), 1);
        assert_eq!(graph["domain"]["id"], "patchback");
        assert_eq!(graph["domain"]["summary"], SYSTEM_SUMMARY);
    }

    #[test]
    fn map_and_wrapper_types_are_named_with_their_parameters() {
        let map = json!({"kind": "map", "key": "string",
                         "value": {"kind": "declared", "name": "x.patch.ParameterValue"}});
        assert_eq!(type_name(&map).unwrap(), "Map<string, ParameterValue>");
        let list = json!({"kind": "list", "of": {"kind": "primitive", "name": "Decimal"}});
        assert_eq!(type_name(&list).unwrap(), "List<Decimal>");
        assert!(type_name(&json!({"kind": "tuple"})).is_err());
    }

    #[test]
    fn a_relation_to_an_undeclared_entity_is_refused() {
        let mut model = model();
        model["entities"]["x.fit.FitRun"]["relations"][0]["target"] = json!("x.nowhere.Thing");
        assert!(domain_graph(&model, "x.fit").is_err());
    }
}
